) AS (
  VALUES 
    (471::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2024-06-10T00:00:00+00:00'::TIMESTAMPTZ, 'd7035047449fd942ed4efd9fd7fd48c99e451c544c8d6bde188eabe9644148cd'::TEXT, ARRAY[3092]::BIGINT[]),
    (471::BIGINT, 'La profe es demasiado buena, es una excelente profesional y tiene demasiado conocimiento que dar. Siempre está dispuesta a ayudar al estudiante y brindarles retroalimentación'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Clases excelentes']::TEXT[], '2024-06-10T00:00:00+00:00'::TIMESTAMPTZ, 'ef8f8454c0e8fb6cffc46b6fec9c34b00cf7feea4cc7a02d5c562e9096224056'::TEXT, ARRAY[4067, 3092]::BIGINT[]),
    (471::BIGINT, 'La profe tiene mucho conocimiento y siempre está dispuesta a ayudar a los estudiantes en todo lo que pueda y no sólo en sus cursos. Las clases son muy entretenidas e interesantes. Además, es muy linda persona y amable con los estudiantes. Se aprende demasiado con ella.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-10T00:00:00+00:00'::TIMESTAMPTZ, '939a594bfc5b2bee42ed5614d2c1e56fb170f64046fe438e12ee5cb7b2a38d5e'::TEXT, ARRAY[3092, 4067]::BIGINT[]),
    (471::BIGINT, 'Las clases de la profe son muy enriquecedoras, se aprende un montón. Ella siempre está dispuesta a antender dudas y apoya un montón a los estudiantes.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2024-06-10T00:00:00+00:00'::TIMESTAMPTZ, 'b01b0faef818c017e0ada1b35f9e82554f436abf4f52ecf20c5b51ec1e4f19d8'::TEXT, ARRAY[1474]::BIGINT[]),
    (471::BIGINT, 'Excelente profesora, siempre dispuesta a ayudar al estudiante, clases muy interesantes y acertadas. Realmente tiene mucho conocimiento que trasnmitir.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-10T00:00:00+00:00'::TIMESTAMPTZ, '165413b3fb7a72a3bb59dee17b5b811d28a8047650f85bfa9b6dc166bb26607b'::TEXT, ARRAY[3092, 1474]::BIGINT[]),
    (471::BIGINT, 'Muy buena profe, explica muy bien. La disponibilidad para atender consultas es muy flexible.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-10T00:00:00+00:00'::TIMESTAMPTZ, 'ed443317c9025324915841ef20856dfb77bd53a0901a4d01dfb52cc46f21f0d2'::TEXT, ARRAY[1474]::BIGINT[]),
    (471::BIGINT, 'Es una excelente profe. Siempre esta dispuesta a ayudar y aclarar dudas. Excelente explicando.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2024-06-10T00:00:00+00:00'::TIMESTAMPTZ, 'c1e4a7f6ff1766bfc2b06b2d03445ed6b6e5fcbd208cc85f053c58a773615d22'::TEXT, ARRAY[4067, 3092]::BIGINT[]),
    (471::BIGINT, 'Al principio puede parecer fría pero cuando uno la conoce es todo lo contrario. Ayuda mucho, es muy amable, siempre está dispuesta ayudar y sabe demasiado de todo.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2024-06-10T00:00:00+00:00'::TIMESTAMPTZ, '7a421fa477d7b1b2dd5e8abb82af3fe93c93ff22de4a6f7d6dda54601e427b67'::TEXT, ARRAY[3092, 4067]::BIGINT[]),
    (471::BIGINT, 'Es una excelente profesora, en las clases se interactúa mucho y se discuten los temas, lo que aporta mucho en el aprendizaje. Importatisimo es asistir siempre a clases, lo que la profe explica es lo que más vale.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Clases excelentes']::TEXT[], '2024-06-10T00:00:00+00:00'::TIMESTAMPTZ, 'c222358955abc34ccbcd8c6f2ca1925f016299f86de3e9f49abbf85be920f9fa'::TEXT, ARRAY[3092, 1474]::BIGINT[]),
    (471::BIGINT, 'Es una excelente profesora, es muy comprensiva y da mucha retroalimentación. Si es necesario explica una y otra vez hasta poder ayudarlo a uno y siempre se preocupa por el bienestar de sus estudiantes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-10T00:00:00+00:00'::TIMESTAMPTZ, '2f54ec7f6f6a1e4e1c9695d014547026fe5b804fd620a68335df68ff992abc8e'::TEXT, ARRAY[1474]::BIGINT[]),
    (471::BIGINT, 'Excelente profesora, es muy comprensiva y accesible, tiene muchísimo conociimiento de la materia'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2024-06-10T00:00:00+00:00'::TIMESTAMPTZ, '1b834ccdbf7a8f2f3392eacdaf0355a3c7769824f9049e56d8bed90ca097bb7c'::TEXT, ARRAY[4067]::BIGINT[]),
    (471::BIGINT, 'La mejor profesora, atenta, explica bien y es totalmente clara. Definitivamente merece una mejor calificación'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2024-06-10T00:00:00+00:00'::TIMESTAMPTZ, '5158d53191cef496189020340f18358f2b02bd962fd2aefebb24da8596d777be'::TEXT, ARRAY[1474]::BIGINT[]),
    (471::BIGINT, 'Nunca pasa lista entonces es vara ir, hace trabajos en equipo que son super faciles, los examenes son super faciles tambien, en general la clase es ir a escucharla leer diapositivas, pero el curso se pasa practicamente solo, mientras uno lleve todo al dia.'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2024-05-17T00:00:00+00:00'::TIMESTAMPTZ, '129d7e408dd8ffe0955040efccb3f7be0fb373eee1905a141d1e50568fb58939'::TEXT, ARRAY[1592, 4053]::BIGINT[]),
    (471::BIGINT, 'No sabe explicar, uno debe buscar por otros medios entender la materia porque la clase no es suficiente. Además de lo anterior la clase se vuelve pesada y aburrida'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '87c3a7a1c501d24c181f0e5132a0b4e4da2ffc80b5faf7f0963bd5d53b93b007'::TEXT, ARRAY[3092, 1474]::BIGINT[]),
    (471::BIGINT, 'La profe es súper amable y siempre está dispuesta a ayudar al estudiante. Explica más teoría que ejercicios prácticos. Las clases sí son largas, por lo tanto se hacen cansadas de llevar(virtual). Aparte de eso, uno aprende mucho!'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases largas', 'Aspectos de calificación claros']::TEXT[], '2021-11-24T00:00:00+00:00'::TIMESTAMPTZ, 'c1ca25ba199a59eac75bc322a6e8930fbe051f5599229c003edea889b4c8d2d9'::TEXT, ARRAY[4067, 3092]::BIGINT[]),
    (471::BIGINT, 'La profe es buena gente, pero es muy mala explicando, se basa solo en la teoría y casi no explica la parte practica, la clase es verla leer presentaciones y resolver un ejercicio si topa con suerte dos. Solo resuelve ejercicios en consulta. Los ejercicios que da en clases son muy básicos'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2020-11-17T00:00:00+00:00'::TIMESTAMPTZ, '640dfd26922aff5cda0d7660592d75abac346d049964642342e2481c134069ed'::TEXT, ARRAY[3092]::BIGINT[]),
    (471::BIGINT, 'Ella es un amor de persona, realmente es muy buena. A mi parecer ella sí explica bien, en general es una excelente profe y muy buena persona'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2019-10-02T00:00:00+00:00'::TIMESTAMPTZ, '3284413d0fe3ff200e8a6f9c77a637c95c5de75c6405be31f85616f310993f6d'::TEXT, ARRAY[3092]::BIGINT[]),
    (471::BIGINT, 'Muy buena profesora, sabe demasiado, aclara todas las dudas, tiene mucha paciencia y es super buena gente.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '90a56b13817567a8cd1bb8245c99bb0ef1c3fccaec0569435dbb8c92a997a079'::TEXT, ARRAY[1474]::BIGINT[]),
    (471::BIGINT, 'Con la Profe, hay que prestar mucha atención en el armado de los equipos (especialmente los trenes de muestreo). Ya que, explica y luego hay que armarlos en equipos de trabajo y es preferible que cada uno lo haga. Hay que tomar muchos apuntes porque la profe dicta todo y hay que ser ordenado.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2018-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'd59bfd41530925397e69e1b49468d2ecc33375b2c37b6adc5e80093be98dc4c3'::TEXT, ARRAY[1483]::BIGINT[]),
    (471::BIGINT, 'Las clases son algo desordenadas, cuesta entenderle cuando resuelve ejercicios. Habla un poco bajo, pero sube las presentaciones al Tec-Digital. En consulta es buena gente, procura aclarar dudas. Los exámenes que realiza son un poco confusos. Califica justo (no regala puntos en el examen).'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Brinda apoyo']::TEXT[], '2017-06-28T00:00:00+00:00'::TIMESTAMPTZ, '55add15bdad99c34d2edb91b735f928b55cfa3946279390913d1639e8fb05b9b'::TEXT, ARRAY[1474]::BIGINT[]),
    (471::BIGINT, 'Como persona excelente , como profe malísima . Demasiado desorden , los contenidos son poco organizados.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Exámenes retadores']::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'c977d1e9d9e9f624a359d696b71ebdc471d7e112fb64930fd62d5be778865132'::TEXT, ARRAY[4067]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
